import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import classList from 'flarum/common/utils/classList';
import IndexPage from 'flarum/forum/components/IndexPage';
import Sidebar from './components/Sidebar';
import { closeDrawer, isDrawerOpen, toggleDrawer } from './drawer';
import formatCount from './formatCount';
import { canStart, extensionEnabled, startDiscussion, tagsEnabled, t, ts } from './util';

/**
 * The parts of Concourse that are on every page: the left sidebar, and on
 * phones the tab bar along the bottom.
 *
 * 🚨 Mounted next to the router rather than inside a page, the same way core
 * mounts its own header. A page component only exists while its route does,
 * so a sidebar drawn by IndexPage would vanish on every discussion and
 * profile; mounted here it is one element for the whole visit, and `m.mount`
 * puts it on the same redraw as everything else.
 */
export default function installShell() {
  extend(app, 'mount', () => {
    const root = document.getElementById('app');
    if (!root) return;
    const mount = (className, component) => {
      const el = document.createElement('div');
      el.className = className;
      root.append(el);
      m.mount(el, component);
    };
    mount('ConcourseShell-sidebar', Sidebar);
    mount('ConcourseShell-tabbar', TabBar);

    // The scrim behind the open drawer; a tap on it closes the drawer.
    const scrim = document.createElement('div');
    scrim.className = 'ConcourseShell-scrim';
    scrim.addEventListener('click', closeDrawer);
    root.append(scrim);
    document.addEventListener('keydown', e => {
      if (e.key === 'Escape' && isDrawerOpen()) closeDrawer();
    });
  });
}

/** The phone's tab bar: Home, Tags, New, Messages, More. */
const TabBar = {
  view() {
    const user = app.session.user;
    const route = m.route.get() || '/';
    const messages = !!user && extensionEnabled('flarum-messages');
    const unread = user && user.attribute('unreadDialogCount') || 0;

    // Unkeyed on purpose: which tabs exist changes (no Messages for a guest),
    // and Mithril refuses a mix of keyed tabs and empty slots.
    const tab = (icon, label, href, active, badge = 0) => m(Link, {
      href: href,
      className: classList('ConcourseTab', {
        active
      }),
      "aria-current": active ? 'page' : undefined,
      onclick: closeDrawer
    }, m("span", {
      className: "ConcourseTab-icon"
    }, m(Icon, {
      name: icon
    }), badge ? m("span", {
      className: "ConcourseTab-badge"
    }, formatCount(badge)) : null), m("span", {
      className: "ConcourseTab-label"
    }, label));
    return m("nav", {
      className: "ConcourseTabBar",
      "aria-label": ts('phone.tabs')
    }, tab('fas fa-house', t('sidebar.home'), app.route('index'), app.current.matches(IndexPage) && !isDrawerOpen() && route === '/'), tagsEnabled() ? tab('fas fa-tags', t('sidebar.tags'), app.route('tags'), route.startsWith('/tags')) : null, canStart() ? m("button", {
      type: "button",
      className: "ConcourseTab ConcourseTab--new",
      "aria-label": app.translator.trans('core.forum.index.start_discussion_button', {}, true),
      onclick: () => {
        closeDrawer();
        startDiscussion();
      }
    }, m("span", {
      className: "ConcourseTab-plus"
    }, m(Icon, {
      name: "fas fa-plus"
    }))) : null, messages ? tab('far fa-envelope', t('phone.messages'), app.route('messages'), route.startsWith('/messages'), unread) : null, m("button", {
      type: "button",
      className: classList('ConcourseTab', {
        active: isDrawerOpen()
      }),
      "aria-expanded": isDrawerOpen() ? 'true' : 'false',
      onclick: toggleDrawer
    }, m("span", {
      className: "ConcourseTab-icon"
    }, m(Icon, {
      name: "fas fa-bars"
    })), m("span", {
      className: "ConcourseTab-label"
    }, t('phone.more'))));
  }
};